INSERT INTO document_chunks (id, source_file, chunk_index, content, metadata, embedding)
VALUES (
    'chunk_7f1f691e8381',
    'converted_sql-sql-server-ver17.md',
    56303,
    '### SQL

Permissions
Examples
DECLARE @dialog_handle UNIQUEIDENTIFIER,
    @ExpenseReport XML;
SET @ExpenseReport = <construct message as appropriate for the application>;
BEGIN DIALOG @dialog_handle
    FROM SERVICE [//Adventure-Works.com/Expenses/ExpenseClient]
    TO SERVICE ''//Adventure-Works.com/Expenses''
    ON CONTRACT [//Adventure-Works.com/Expenses/ExpenseProcessing];
SEND ON CONVERSATION @dialog_handle
    MESSAGE TYPE [//Adventure-Works.com/Expenses/SubmitExpense](@ExpenseReport);



BEGIN DIALOG CONVERSATION (Transact-SQL)
END CONVERSATION (Transact-SQL)
RECEIVE (Transact-SQL)
sys.transmission_queue (Transact-SQL)',
    '{"section":"SQL","page_anchor":"PAGE 30671","char_length":633}'::jsonb,
